xM(a){return"\ubaa9\ud45c\ubcf4\ub2e4 "+a+"% \ub0ae\uc558\uc5b4\uc694. \ub2e4\uc74c \uc138\uc158\uc5d0 \ubc18\uc601\ub3fc\uc694."},
xL(a){return"\uc9c0\uae08\uae4c\uc9c0 \ucd5c\uace0 \uae30\ub85d: "+a+"."},
xE(a){return"\ucd94\uc815 \ub2a5\ub825\uc774 "+a+" \ubcc0\ud588\uc5b4\uc694."},
gxG(){return"\ud798\ub4e4\ub2e4\uace0 \ud45c\uc2dc\ud588\uc5b4\uc694. \ubc18\ubcf5\ub418\uba74 \ud50c\ub79c \ud398\uc774\uc2a4\ub97c \uc870\uc815\ud560\uac8c\uc694."},
gxF(){return"\uc27d\ub2e4\uace0 \ud45c\uc2dc\ud588\uc5b4\uc694. \ubc18\ubcf5\ub418\uba74 \ud50c\ub79c\uc744 \ub354 \ube60\ub974\uac8c \ud560 \uc218 \uc788\uc5b4\uc694."},
xK(a){return"\ud398\uc774\uc2a4: "+a+"\ubd84/km."},
xJ(a,b){return"\ub2e4\uc74c \uc138\uc158: "+a+", \ud50c\ub79c\uc0c1 "+b+"."},
gq6(){return"\uc624\ub298\uc758 \ucd94\ucc9c"},
vx(a){return a+" \uc2dc\uc791"},
v1(a){return"\uc624\ub298 "+a+" \uc644\ub8cc"},
vi(a,b){return b+" \ubaa9\ud45c\uc758 "+a+"%\uc5d0 \ub3c4\ub2ec\ud588\uc5b4\uc694."},
v3(a){return a+" \ubaa9\ud45c\ub97c \ub2ec\uc131\ud588\uc5b4\uc694."},
gvt(){return"\uacc4\ud68d\ud588\ub358 \ub0a0\uc774\uc5d0\uc694"},
vr(a){var s=null
return A.dt(a,s,this.a,s,s,""+a+"\uc77c \uc804 \uacc4\ud68d\uc774\uc5c8\uace0 \uc544\uc9c1 \ub0a8\uc544 \uc788\uc5b4\uc694",s,s)},
gvw(){return"\uc774\ubc88 \uc8fc\ub97c \ucc44\uc6b8 \ub0a0\uc774 \uc5bc\ub9c8 \ub0a8\uc9c0 \uc54a\uc558\uc5b4\uc694"},
gvq(){return"\uadf8 \uadfc\uc721\uc740 \ucda9\ubd84\ud788 \uc26c\uc5c8\uc5b4\uc694"},
gvo(){return"\uacc4\ud68d\ubcf4\ub2e4 \ub4a4\ucc98\uc838 \uc788\uc5b4\uc694"},
vp(a){return""+a+"\uc77c \ub3d9\uc548 \ud558\uc9c0 \uc54a\uc558\uc5b4\uc694"},
